*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#0b0a0c;color:#f5e8dc}body{display:grid;place-items:center;font-family:var(--display);user-select:none;-webkit-user-select:none}#game-shell{width:min(100vw,calc(100vh * 1.7778),1280px);padding:16px 22px 10px;position:relative}#game-frame{width:100%;aspect-ratio:16/9;position:relative;overflow:hidden;background:#151114;border:1px solid #55413b;box-shadow:0 0 0 1px #171316,0 20px 70px #000b,0 0 65px #bd37241c}canvas{width:100%;height:100%;display:block;image-rendering:pixelated;background:#171117}.scanlines{position:absolute;inset:0;pointer-events:none;z-index:2;background:linear-gradient(180deg,#0d091014 50%,#08070a43 50%);background-size:100% 4px;box-shadow:inset 0 0 90px #070608b8}.topline{position:absolute;z-index:4;top:17px;left:22px;right:22px;display:flex;justify-content:space-between;color:#d0bdb3;font:11px var(--mono);letter-spacing:.11em;text-shadow:0 2px 6px #000}.topline b{font-weight:400;color:#f86c48}.topline i,.footline i{font-style:normal;color:#e2664d}.sector{color:#aa9a91}.hud{position:absolute;z-index:4;left:19px;right:19px;bottom:15px;display:flex;align-items:end;justify-content:space-between;pointer-events:none;text-shadow:0 2px 5px #000}.hud-stat{width:155px;height:53px;padding:8px 10px;background:linear-gradient(90deg,#100e12c9,#1711169c);border-left:2px solid #e2664d}.hud-stat.ammo{border-left:0;border-right:2px solid #e2664d;text-align:right}.label{display:block;color:#ceaaa0;font:10px var(--mono);letter-spacing:.16em}.health .meter{height:5px;width:95px;margin-top:8px;background:#3c2929;display:inline-block;vertical-align:middle}.health .meter i{height:100%;display:block;width:100%;background:#fd5e48;box-shadow:0 0 8px #f54d34}.health>b{font:18px var(--mono);margin-left:7px;vertical-align:middle}.hud-center{text-align:center;width:115px;padding-bottom:4px}.hud-center .label{font-size:9px;color:#ed9b80}.hud-center b{display:block;font:28px var(--display);line-height:26px;color:#ffd2a2;text-shadow:0 0 14px #fa5a35}.hud-center small{font:9px var(--mono);letter-spacing:.12em;color:#e6c6b5}.ammo>b{font:23px var(--mono);display:block;margin:2px 0 1px;color:#fff0df}.ammo>b small{font-size:13px;color:#b19f97}.ammo-pips{height:3px;display:flex;justify-content:flex-end;gap:3px}.ammo-pips i{width:8px;height:3px;background:#fa694b}.ammo-pips i.empty{background:#583c39}.footline{height:27px;display:flex;align-items:end;justify-content:space-between;color:#877a76;font:10px var(--mono);letter-spacing:.08em}.footline b{font-weight:400;color:#d4a08e}.footline i{padding:0 4px}.footline span:last-child{text-align:right}#reticle{position:absolute;z-index:3;left:50%;top:50%;width:18px;height:18px;transform:translate(-50%,-50%);opacity:.84;pointer-events:none;filter:drop-shadow(0 1px 2px #000)}#reticle i,#reticle b,#reticle em,#reticle strong{position:absolute;background:#ffd6b4;display:block}#reticle i,#reticle b{width:1px;height:5px;left:8px}#reticle i{top:0}#reticle b{bottom:0}#reticle em,#reticle strong{height:1px;width:5px;top:8px}#reticle em{left:0}#reticle strong{right:0}.toast{position:absolute;z-index:5;left:50%;top:20%;transform:translate(-50%,-8px);opacity:0;transition:.18s;color:#ffd4b1;font:12px var(--mono);letter-spacing:.18em;text-shadow:0 2px 6px #000;background:#160e12b5;padding:8px 14px;border:1px solid #7d4035;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.interaction{position:absolute;z-index:4;top:58%;left:50%;transform:translateX(-50%);font:11px var(--mono);letter-spacing:.12em;color:#ffd5a1;text-shadow:0 2px 5px black;text-align:center;pointer-events:none}.screen{position:absolute;z-index:6;inset:0;display:grid;place-items:center;background:radial-gradient(ellipse at 50% 42%,#130c0c3d,#0b090cbf 68%,#09080acc);backdrop-filter:blur(2px)}.screen.hidden{display:none}.screen-card{text-align:center;position:relative;width:min(90%,560px);padding:28px 30px 21px;background:linear-gradient(145deg,#191316f2,#100e12f2);border:1px solid #694539;box-shadow:0 15px 70px #000b,inset 0 1px #f5986730}.intro-card:before,.intro-card:after{content:'';position:absolute;width:18px;height:18px;border-color:#fa7951}.intro-card:before{top:-1px;left:-1px;border-top:2px solid;border-left:2px solid}.intro-card:after{right:-1px;bottom:-1px;border-right:2px solid;border-bottom:2px solid}.eyebrow{font:10px var(--mono);letter-spacing:.2em;color:#d2977f}.eyebrow span{display:inline-block;width:25px;height:1px;background:#d4634d;vertical-align:middle;margin:0 9px}.screen h1{font:900 clamp(53px,9vw,90px)/.8 var(--display);letter-spacing:.035em;margin:19px 0 7px;color:#fff0df;text-shadow:0 3px #8f3028,0 7px #3a1c20,0 0 34px #ff593c38}.screen h1 span{color:#ef6849}.subtitle{font:13px var(--mono);letter-spacing:.47em;color:#f5bb88;margin:13px 0 18px}.intro-copy,.compact-card p{color:#b2a19a;font:13px/1.7 var(--mono);margin:0 0 20px}.intro-copy strong{color:#fff0de;font-weight:400}.primary-button{position:relative;min-width:220px;border:1px solid #f2825c;background:#bd4836;color:#fff1df;padding:12px 22px;font:700 15px var(--display);letter-spacing:.12em;cursor:pointer;box-shadow:inset 0 1px #ffb07855,0 5px 16px #a8342733;transition:.16s}.primary-button span{margin-left:13px;color:#ffd0a1}.primary-button:hover{background:#e05b40;transform:translateY(-2px);box-shadow:0 8px 22px #a8342755}.control-hint{margin-top:19px;color:#8e7c77;font:9px var(--mono);letter-spacing:.05em}.control-hint span{color:#e2c6b5}.control-hint i{color:#e2664d;font-style:normal;padding:0 5px}.mobile-hint{display:none}.corner-code{position:absolute;right:18px;bottom:15px;color:#816e69;font:9px/1.55 var(--mono);text-align:right;letter-spacing:.07em}.compact-card{width:min(90%,430px);padding:33px 30px 24px}.compact-card h2{margin:14px 0 13px;font:900 57px/.9 var(--display);color:#fff0df}.compact-card h2 span{color:#f16a48}.compact-card .control-hint{margin-top:22px}.mobile-controls{display:none}
@media(max-width:700px){#game-shell{width:100vw;padding:0}#game-frame{border:0;aspect-ratio:auto;height:100dvh}.topline{top:max(12px,env(safe-area-inset-top));left:13px;right:13px;font-size:9px}.sector{font-size:9px}.hud{left:10px;right:10px;bottom:calc(120px + env(safe-area-inset-bottom));}.hud-stat{width:112px;height:47px;padding:7px 7px}.label{font-size:8px}.health .meter{width:65px;margin-top:7px}.health>b{font-size:15px;margin-left:4px}.ammo>b{font-size:18px}.ammo>b small{font-size:11px}.hud-center{width:80px}.hud-center b{font-size:23px}.hud-center small{font-size:8px}.footline{display:none}.screen-card{padding:23px 15px 17px}.screen h1{font-size:clamp(54px,17vw,80px)}.intro-copy{font-size:11px}.control-hint{display:none}.mobile-hint{display:block;color:#907d76;font:9px var(--mono);letter-spacing:.12em;margin-top:15px}.corner-code{display:none}.mobile-controls{display:block;position:absolute;z-index:5;bottom:calc(15px + env(safe-area-inset-bottom));left:0;right:0;height:112px;pointer-events:none}.stick{width:104px;height:104px;position:absolute;bottom:0;pointer-events:auto;touch-action:none}.move-stick{left:16px}.aim-stick{right:16px}.stick-ring{position:absolute;inset:7px;border:1px solid #f0c3ac55;border-radius:50%;background:#25171b55;box-shadow:inset 0 0 20px #0007}.stick-knob{position:absolute;width:42px;height:42px;left:31px;top:31px;border:1px solid #f29a7a99;border-radius:50%;background:radial-gradient(circle at 35% 30%,#bb735d99,#482e37cc);box-shadow:0 3px 12px #0008}.stick small{position:absolute;bottom:0;left:0;right:0;text-align:center;color:#bf9d91;font:8px var(--mono);letter-spacing:.16em;text-shadow:0 2px 3px black}.fire-button{pointer-events:auto;touch-action:none;position:absolute;left:50%;top:19px;transform:translateX(-50%);width:59px;height:59px;border:1px solid #ff9a6d;border-radius:50%;color:#ffe0c0;background:radial-gradient(circle,#b74e3c,#632c34);font:700 11px var(--display);letter-spacing:.1em;box-shadow:0 0 18px #ee5d3c4d,inset 0 1px #ffd0a455}.reload-button{pointer-events:auto;touch-action:none;position:absolute;left:50%;bottom:4px;transform:translateX(-50%);height:28px;width:31px;border:1px solid #f0c3ac66;border-radius:50%;color:#e9b69b;background:#21171bcc;font-size:18px;line-height:20px}.interaction{top:54%}.scanlines{background-size:100% 3px}}
@media(max-height:520px) and (max-width:900px){#game-frame{height:100dvh}.mobile-controls{transform:scale(.75);transform-origin:bottom center;bottom:4px}.hud{bottom:92px}.screen-card{transform:scale(.85)}.screen h1{font-size:55px}.intro-copy{margin-bottom:12px}.subtitle{margin:8px 0 12px}}

(()=>{
'use strict';
const canvas=document.getElementById('view'),ctx=canvas.getContext('2d',{alpha:false});
const W=canvas.width,H=canvas.height,TAU=Math.PI*2,FOV=Math.PI*.38;
const mapRows=[
'####################',
'#........#.........#',
'#........#.........#',
'#........#.........#',
'#..................#',
'#..##......##......#',
'#..##......##......#',
'#..................#',
'#..................#',
'#...###.....###....#',
'#...###.....###....#',
'#..................#',
'#...........#......#',
'#...........#......#',
'#.................G#',
'####################'];
const map=mapRows.map(r=>r.split('').map(c=>c==='#'?1:c==='G'?3:c==='.'?0:2));
const $=id=>document.getElementById(id);
const ui={health:$('health-value'),healthFill:$('health-fill'),wave:$('wave-value'),count:$('enemy-count'),ammo:$('ammo-value'),pips:$('ammo-pips'),toast:$('toast'),interaction:$('interaction'),status:$('status-line'),start:$('start-screen'),pause:$('pause-screen'),end:$('end-screen'),endTitle:$('end-title'),endEyebrow:$('end-eyebrow'),endCopy:$('end-copy'),mobile:$('mobile-controls')};
let player,enemies=[],pickups=[],wave=1,kills=0,state='title',last=performance.now(),time=0,toastTimer=0,damageFlash=0,shootFlash=0,recoil=0,shake=0,fireHeld=false,fireCooldown=0,reloadTimer=0,mouseLocked=false,keys={},zBuffer=new Float32Array(W),moveTouch={x:0,y:0},aimTouch={x:0,y:0};
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const norm=a=>{while(a>Math.PI)a-=TAU;while(a< -Math.PI)a+=TAU;return a};
const cell=(x,y)=>map[y]?.[x]??1;
function solid(x,y){const t=cell(Math.floor(x),Math.floor(y));return t===1||t===2||(t===3&&wave<4)}
function canStand(x,y,r=.2){return !solid(x-r,y-r)&&!solid(x+r,y-r)&&!solid(x-r,y+r)&&!solid(x+r,y+r)}
function reset(){player={x:2.5,y:2.5,a:.08,hp:100,ammo:8,reserve:32,flash:0,walk:0,damage:0};wave=1;kills=0;enemies=[];pickups=[];spawnWave();state='playing';ui.start.classList.add('hidden');ui.end.classList.add('hidden');ui.pause.classList.add('hidden');ui.mobile.style.display='';toast('BREACH CONFIRMED — CLEAR THE SECTOR');updateHud()}
function spawnWave(){let spots=wave===1?[[6.6,2.5,'imp'],[15.5,5.5,'imp'],[13.3,11.7,'imp']]:wave===2?[[7.2,7.5,'imp'],[16.7,3.8,'imp'],[5.6,12.5,'brute'],[16.5,12.3,'imp']]:[[6.2,8.2,'brute'],[15.8,7.4,'brute'],[3.5,12.5,'imp'],[17.1,3.8,'imp'],[10.5,11.2,'brute']];
 for(let [x,y,type] of spots)enemies.push({x,y,type,hp:type==='brute'?100:58,max:type==='brute'?100:58,speed:type==='brute'?.48:.72,attack:0,stagger:0,frame:Math.random()*6,route:[{x,y}],pathTimer:0,dead:false});ui.wave.textContent=String(wave).padStart(2,'0');updateHud()}
function startGame(){if(state==='title'||state==='dead'||state==='won')reset();if(canvas.requestPointerLock&&!isTouch())canvas.requestPointerLock().catch?.(()=>{});}
function isTouch(){return matchMedia('(pointer:coarse)').matches||navigator.maxTouchPoints>0}
function toast(msg){ui.toast.textContent=msg;ui.toast.classList.add('show');toastTimer=2.2}
function updateHud(){ui.health.textContent=Math.max(0,Math.ceil(player?.hp||100));ui.healthFill.style.width=`${clamp(player?.hp||100,0,100)}%`;ui.healthFill.style.background=player&&player.hp<30?'#ff3e42':'#fd5e48';if(player){ui.ammo.innerHTML=`${String(player.ammo).padStart(2,'0')} <small>/ ${String(player.reserve).padStart(2,'0')}</small>`;ui.pips.innerHTML=Array.from({length:8},(_,i)=>`<i class="${i>=player.ammo?'empty':''}"></i>`).join('')}let live=enemies.filter(e=>!e.dead).length;ui.count.textContent=`${live} HOSTILE${live===1?'':'S'}`}
function wallRay(angle){let dx=Math.cos(angle),dy=Math.sin(angle),mx=Math.floor(player.x),my=Math.floor(player.y),ddx=Math.abs(1/(dx||1e-9)),ddy=Math.abs(1/(dy||1e-9)),sx=dx<0?-1:1,sy=dy<0?-1:1,sdx=(dx<0?player.x-mx:mx+1-player.x)*ddx,sdy=(dy<0?player.y-my:my+1-player.y)*ddy,side=0,tile=1;for(let i=0;i<64;i++){if(sdx<sdy){sdx+=ddx;mx+=sx;side=0}else{sdy+=ddy;my+=sy;side=1}tile=cell(mx,my);if(tile){let d=side?sdy-ddy:sdx-ddx;let wall=(side?player.x+dx*d:player.y+dy*d);wall-=Math.floor(wall);return {d:Math.max(.001,d),side,wall,tile,mx,my}}}return{d:20,side:0,wall:0,tile:1,mx,my}}
function wallColor(hit,texY){let {tile,side,wall,mx,my}=hit;let mortar=(Math.floor(texY/13)+((my*13+mx*7)&1))%5===0;let seam=(Math.floor(wall*10)%5===0);let r,g,b;if(tile===3){r=115+Math.sin(texY*.13+time*2)*16;g=29;b=31;if(seam||mortar){r+=55;g+=24;b+=13}}else{let brickRow=Math.floor(texY/13),brickCol=Math.floor(wall*9+(brickRow%2)*.5),n=Math.sin((mx*83+my*31+brickRow*17+brickCol*9)*7.1)*12;r=82+n;g=42+n*.55;b=39+n*.4;if(seam||mortar){r=41;g=30;b=32}if(tile===2){r+=27;g+=18;b+=18}}let shade=(side?.73:1)*(1-clamp(hit.d/14,0,.7));let grit=(Math.sin(wall*211+texY*57+mx*23+my)*.5+.5)*10;return `rgb(${clamp((r+grit)*shade,0,255)|0},${clamp((g+grit*.6)*shade,0,255)|0},${clamp((b+grit*.4)*shade,0,255)|0})`}

input.newString:
return `rgb(${clamp((r+grit)*shade,0,255)|0},${clamp((g+grit*.6)*shade,0,255)|0},${clamp((b+grit*.4)*shade,0,255)|0})`}
function renderWorld(){let sky=ctx.createLinearGradient(0,0,0,H*.52);sky.addColorStop(0,'#1c151d');sky.addColorStop(.55,'#49241f');sky.addColorStop(1,'#b84d2e');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H*.53);ctx.fillStyle='#ff8b4b';ctx.globalAlpha=.35;ctx.beginPath();ctx.ellipse(W*.52,H*.43,115,22,0,0,TAU);ctx.fill();ctx.globalAlpha=1;
 let horizon=H*.49+(Math.sin(player.walk)*1.3);let floor=ctx.createLinearGradient(0,horizon,0,H);floor.addColorStop(0,'#28171a');floor.addColorStop(.55,'#21151b');floor.addColorStop(1,'#100e14');ctx.fillStyle=floor;ctx.fillRect(0,horizon,W,H-horizon);
 for(let y=Math.floor(horizon)+1;y<H;y++){let rowDist=(H*.48)/(y-horizon);if(rowDist>18)continue;let a=player.a-FOV/2;for(let x=0;x<W;x+=8){let ra=a+x/W*FOV,wx=player.x+Math.cos(ra)*rowDist,wy=player.y+Math.sin(ra)*rowDist;let grid=(Math.floor(wx*2)+Math.floor(wy*2))%2===0;let distShade=clamp(1-rowDist/12,.15,1);ctx.fillStyle=grid?`rgba(120,54,41,${.17*distShade})`:`rgba(6,5,10,${.22*distShade})`;ctx.fillRect(x,y,8,1)}}
 for(let x=0;x<W;x+=2){let ang=player.a-FOV/2+x/W*FOV,h=wallRay(ang),dist=h.d*Math.cos(ang-player.a);zBuffer[x]=zBuffer[x+1]=dist;let wh=Math.min(H*2,H*1.05/dist),top=horizon-wh/2;let step=Math.max(1,Math.floor(wh/45));for(let yy=Math.max(0,top);yy<Math.min(H,top+wh);yy+=step){let ty=(yy-top)/wh*90;ctx.fillStyle=wallColor(h,ty);ctx.fillRect(x,yy,2,step+1)}if(h.tile===3){ctx.fillStyle=`rgba(255,87,46,${.08+Math.sin(time*5+h.wall*10)*.05})`;ctx.fillRect(x,top,2,wh)}}
 drawDecor();drawActors();drawWeapon();if(damageFlash>0){ctx.fillStyle=`rgba(185,25,25,${damageFlash*.16})`;ctx.fillRect(0,0,W,H)}if(shake>0){/* camera kick is represented in the weapon */}}
function drawDecor(){// distant braziers and industrial silhouettes, painted into the skyline
 for(let i=0;i<8;i++){let wx=1.2+i*2.35,wy=i%2?1.1:14.8,ang=norm(Math.atan2(wy-player.y,wx-player.x)-player.a),d=Math.hypot(wx-player.x,wy-player.y);if(Math.abs(ang)>FOV*.62||d<1)continue;let sx=W/2+ang/FOV*W,sy=H*.49-d*1.7,sz=clamp(35/d,2,16);if(sx<0||sx>W)continue;ctx.fillStyle='#20171b';ctx.fillRect(sx-sz*.22,sy-sz*2,sz*.44,sz*2);ctx.fillStyle='#8c3a28';ctx.fillRect(sx-sz*.32,sy-sz*2.2,sz*.64,sz*.28);ctx.fillStyle=`rgba(255,108,49,${.35+Math.sin(time*5+i)*.16})`;ctx.fillRect(sx-sz*.18,sy-sz*2.7,sz*.36,sz*.6)}}
function drawActors(){let list=[...enemies.filter(e=>!e.dead).map(e=>({...e,kind:'enemy'})),...pickups.map(p=>({...p,kind:'pickup'}))].sort((a,b)=>Math.hypot(b.x-player.x,b.y-player.y)-Math.hypot(a.x-player.x,a.y-player.y));for(let e of list){let dx=e.x-player.x,dy=e.y-player.y,d=Math.hypot(dx,dy),ang=norm(Math.atan2(dy,dx)-player.a);if(Math.abs(ang)>FOV*.62||d<.2)continue;let sx=W/2+ang/FOV*W,dist=d*Math.cos(ang);if(sx< -100||sx>W+100)continue;if(e.kind==='pickup'){drawPickup(e,sx,dist);continue}let h=Math.min(185,147/dist)*(e.type==='brute'?1.2:1),w=h*.68,bottom=H*.5+h*.49;if(zBuffer[clamp(sx|0,0,W-1)]<dist-.16)continue;drawDemon(e,sx,bottom,w,h,dist)}}
function drawDemon(e,x,bottom,w,h,d){ctx.save();ctx.translate(x,bottom);ctx.scale(w/90,h/120);ctx.globalAlpha=clamp(1-d/17,.24,1);let sway=Math.sin(time*4+e.frame)*2,red=e.type==='brute';ctx.fillStyle='#09090c88';ctx.beginPath();ctx.ellipse(0,2,35,7,0,0,TAU);ctx.fill();
 // legs / hooves
 ctx.fillStyle=red?'#442329':'#382026';ctx.beginPath();ctx.moveTo(-20,-38);ctx.lineTo(-27,-9);ctx.lineTo(-19,0);ctx.lineTo(-5,-1);ctx.lineTo(-8,-33);ctx.moveTo(6,-35);ctx.lineTo(7,-7);ctx.lineTo(20,0);ctx.lineTo(28,-3);ctx.lineTo(19,-40);ctx.fill();ctx.fillStyle='#130f13';ctx.fillRect(-21,-3,15,4);ctx.fillRect(18,-3,14,4);
 // torso silhouette
 ctx.fillStyle=red?'#6c2b2c':'#693b35';ctx.beginPath();ctx.moveTo(-23,-78);ctx.lineTo(-34,-65);ctx.lineTo(-27,-36);ctx.lineTo(-16,-31);ctx.lineTo(18,-32);ctx.lineTo(29,-47);ctx.lineTo(32,-67);ctx.lineTo(18,-81);ctx.closePath();ctx.fill();ctx.fillStyle=red?'#a04437':'#a35b43';ctx.beginPath();ctx.moveTo(-17,-75);ctx.lineTo(-8,-69);ctx.lineTo(-4,-38);ctx.lineTo(-19,-38);ctx.lineTo(-27,-64);ctx.fill();ctx.fillStyle='#2a171d';ctx.fillRect(-8,-67,17,27);ctx.fillStyle='#f67443';ctx.fillRect(-3,-63,5,20);ctx.fillStyle='#ffd176';ctx.fillRect(-2,-59,2,11);
 // arms/claws
 ctx.fillStyle=red?'#5c252a':'#53302e';ctx.beginPath();ctx.moveTo(-26,-73);ctx.lineTo(-38,-65);ctx.lineTo(-40+sway,-43);ctx.lineTo(-33,-35);ctx.lineTo(-22,-45);ctx.lineTo(-18,-62);ctx.moveTo(22,-72);ctx.lineTo(37,-67);ctx.lineTo(42-sway,-48);ctx.lineTo(34,-37);ctx.lineTo(23,-47);ctx.closePath();ctx.fill();ctx.fillStyle='#d3a27c';ctx.beginPath();ctx.moveTo(-35,-39);ctx.lineTo(-43,-31);ctx.lineTo(-37,-34);ctx.lineTo(-34,-26);ctx.lineTo(-30,-36);ctx.moveTo(35,-40);ctx.lineTo(43,-31);ctx.lineTo(38,-34);ctx.lineTo(35,-26);ctx.lineTo(31,-37);ctx.fill();
