function moveBody(obj,dx,dy,r=.2){if(canStand(obj.x+dx,obj.y,r))obj.x+=dx;if(canStand(obj.x,obj.y+dy,r))obj.y+=dy}
function update(dt){time+=dt;fireCooldown=Math.max(0,fireCooldown-dt);shootFlash=Math.max(0,shootFlash-dt);recoil=Math.max(0,recoil-dt*5.2);damageFlash=Math.max(0,damageFlash-dt*1.6);shake=Math.max(0,shake-dt*14);if(toastTimer>0&&(toastTimer-=dt)<=0)ui.toast.classList.remove('show');if(state!=='playing')return;
 if(reloadTimer>0&&(reloadTimer-=dt)<=0){let take=Math.min(8-player.ammo,player.reserve);player.ammo+=take;player.reserve-=take;updateHud()}
